export {
  createAgentStateTracker,
  TRACKED_EVENTS,
  type AgentState,
  type AgentStateOptions,
} from './tracker.ts';
export { exec, type ExecOptions, type ExecResult } from './exec.ts';
export { createLocationFilter, eventSessionID } from './location.ts';
export { createViewFilter } from './view.ts';
export type { EventOf, FormField, FormInfo, OpenCodeEvent } from './opencode.ts';
export type { WaitingDetail, WaitingQuestion, WaitingQuestionOption } from './waiting.ts';

import type { Plugin } from '@opencode/plugin';

export default {
  id: 'PLUGIN-NAME',
  setup(ctx) {
    const controller = new AbortController();

    void (async () => {
      for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
        void event;
      }
    })();

    return () => controller.abort();
  },
} satisfies Plugin.Plugin;

import { hostname } from 'node:os';
import type { Plugin } from '@opencode/plugin';
import { exec } from '../../_shared/src/index.ts';
import type { ShellInput, ShellMetadata } from './history.ts';
import { AUTHOR, exitCode, isRunning, startArgs } from './history.ts';

const SHELL_TOOL = 'shell';

export default {
  id: 'opencode-atuin-history',
  async setup(ctx) {
    const uuid = await exec('atuin', ['uuid']);
    if (uuid.code !== 0) return;

    const session = uuid.stdout.trim();
    const env: Record<string, string> = {
      ATUIN_HISTORY_AUTHOR: AUTHOR,
      ATUIN_HOST_NAME: `${AUTHOR}@${hostname().split('.')[0]}`,
    };
    if (session) env['ATUIN_SESSION'] = session;

    const started = new Map<string, number>();

    await ctx.shell.hook('create.before', (event) => {
      Object.assign(event.env, env);
    });

    await ctx.tool.hook('execute.before', (event) => {
      if (event.tool === SHELL_TOOL) started.set(event.id, Date.now());
    });

    await ctx.tool.hook('execute.after', async (event) => {
      if (event.tool !== SHELL_TOOL) return;
      const start = started.get(event.id);
      started.delete(event.id);
      if (event.status !== 'completed') return;

      const input = event.input as ShellInput | undefined;
      const command = input?.command;
      if (typeof command !== 'string' || !command) return;

      const history = await exec('atuin', startArgs(command, input), { env });
      const id = history.stdout.trim();
      if (history.code !== 0 || !id) return;

      const metadata = event.result.metadata as ShellMetadata | undefined;
      if (isRunning(metadata)) return;

      const args = ['history', 'end', '--exit', String(exitCode(metadata))];
      if (start !== undefined) args.push('--duration', String((Date.now() - start) * 1e6));
      await exec('atuin', [...args, '--', id], { env });
    });
  },
} satisfies Plugin.Plugin;

import type { Plugin } from '@opencode/plugin';
import { withoutNotices } from './notice';

export default {
  id: 'opencode-cache-coach',
  async setup(ctx) {
    for (const kind of ['context', 'generate', 'compaction', 'title'] as const)
      await ctx.session.hook(kind, (event) => {
        event.messages = withoutNotices(event.messages);
      });
  },
} satisfies Plugin.Plugin;

// This server entry point owns each session's targets: the
// `set_session_target` tool, the agent guidance, and the title prefix. It
// also watches the PRs/MRs of the sessions that CLIs show and tells sessions
// about their reviews. OpenCode loads the package's CLI entry point, tui.tsx,
// which renders the status that this entry point serves.
import type { Plugin } from '@opencode/plugin';
import { exec, execWithTimeout } from './exec';
import { Forges, hostsFrom } from './forges';
import { CONCURRENCY, limitExec } from './limit';
import { createTitleLookups } from './lookups';
import { PLUGIN_ID } from './plugin-id';
import { setupServer } from './server';

export default {
  id: PLUGIN_ID,
  async setup(ctx) {
    const hosts = hostsFrom((ctx.options ?? {}) as Record<string, unknown>);
    // Status polling and feedback fetches share one limit across sessions,
    // and stop running commands once the plugin stops. Title lookups run on
    // their own, so a polling backlog can't delay set_session_target, which
    // waits for the source branch lookup and so also gives up sooner.
    const stopped = new AbortController();
    const statusExec = limitExec(exec, CONCURRENCY, stopped.signal);
    const cleanup = await setupServer(
      ctx,
      createTitleLookups(new Forges(exec, hosts), execWithTimeout(15_000)),
      {
        forges: new Forges(statusExec, hosts),
        exec: statusExec,
      },
    );
    return async () => {
      stopped.abort();
      await cleanup();
    };
  },
} satisfies Plugin.Plugin;

import type { Plugin } from '@opencode/plugin';
import { CONCURRENCY, mapLimit } from './limit';
import {
  FEEDBACK_COMMAND,
  FEEDBACK_TITLE,
  feedbackReport,
  feedbackRef,
  invalidFeedbackReport,
  parseFeedbackAction,
  sessionItems,
  STATUS_COMMAND,
  STATUS_TITLE,
  statusReport,
} from './commands';
import type { TitleLookups } from './lookups';
import { createKeyedQueue } from './keyed-queue';
import { statusOptions } from './options';
import {
  LINKED_NOTE_TOOL,
  restrictRequest,
  summarySystem,
  taggedInput,
  turnInput,
  UNAVAILABLE_TEXT,
  type SummaryRequest,
} from './review-summary';
import { PREPARE_PREFIX } from './review-preparation';
import { storedPreparation } from './review-automation-host';
import { createReviewClaims } from './review-claim';
import { linkedOwner, type DirectorySession } from './linked-session';
import { ForgeSessionRpc, implement } from './rpc';
import { setupStatus, type Status, type StatusDependencies } from './status-server';
import { summaryPrefix } from './summary-delivery';
import type { Snapshot } from './store';
import {
  applyTargetChange,
  includesRequest,
  MAX_TARGETS,
  parseTargetChange,
  targetOutput,
  targetRequest,
  targetsPrefix,
  type Target,
} from './target';
import { branchPrefix, extractIssueNumber, reconcileTitle } from './title';

const SKIP_BRANCHES = new Set(['master', 'main', 'HEAD', 'develop']);

// Stored per session. `prefix` is the title prefix this plugin last wrote, so
// it can be replaced without touching text the user added. Before sessions
// could have several targets, the state held a single `target`.
type StoredState = { targets?: Target[]; prefix?: string };
type SessionState = { targets: Target[]; prefix?: string };

const TARGET_KEY = 'forgekeeper-session-target';
// How many forks back a session without targets looks for inherited ones.
const MAX_FORK_DEPTH = 5;

const GUIDANCE = [
  'When the user establishes or changes the primary issue, PR, or MR for this session, call set_session_target with its full URL before starting that work.',
  'When the user asks you to work on several issues, PRs, or MRs together, call set_session_target with all of their full URLs in targets. If the user describes them instead of linking them, find them first, then set them before starting that work. When they are all PRs/MRs for one established issue, pass it as issue_url.',
  'Reviewing, triaging, or addressing feedback on existing issues, PRs, or MRs makes them the primary targets. Call set_session_target with their full URLs before reading their discussions or changing them, including when a skill, search, or forge listing found them instead of the user linking them.',
  'After you create a PR or MR for the current task (for example with gpsup, glab mr create, gh pr create, or a forge tool), call set_session_target with the new PR/MR URL. Pass the current issue as issue_url when the PR/MR was created for it. If the session has several targets that are still part of the task, use operation "add" so they are kept.',
  'When the user drops some of several targets from the task, call set_session_target with operation "remove" and their URLs.',
  'Background references, comparisons, and dependencies do not change the target. Follow-ups without a new primary target keep the current target.',
  'Include issue_url only when its relationship to the target PRs/MRs is established. Never carry over the checked-out branch’s issue to another target.',
  'When the user explicitly returns to work on the checked-out branch, call set_session_target with target "branch".',
  `The current session target is in the <context> entry "${TARGET_KEY}". The plugin updates it when it changes, so trust the latest value.`,
];

function describeTargets(targets: readonly Target[]): string {
  if (targets.length === 0) return 'checked-out branch (automatic)';
  if (targets.length === 1) return JSON.stringify(targets[0]);
  return `${targets.length} targets: ${JSON.stringify(targets)}`;
}

function toolResult(targets: readonly Target[], missing: readonly string[]): string {
  const lines =
    targets.length === 0
      ? ['Session target: checked-out branch.']
      : targets.length === 1
        ? [`Session target: ${targets[0].url}`]
        : [`Session targets (${targets.length}):`, ...targets.map((target) => `- ${target.url}`)];
  if (missing.length) lines.push(`Not session targets, so not removed: ${missing.join(', ')}`);
  return lines.join('\n');
}

const DISABLED = { enabled: false, snapshot: { loading: false } };

// How long cleanup waits for running title updates. They can't write once
// cleanup starts, so this only bounds how long their lookups are kept.
const DRAIN_TIME = 5_000;

async function drain(tasks: Promise<unknown>[], limit: number) {
  let timer: ReturnType<typeof setTimeout> | undefined;
  await Promise.race([
    Promise.allSettled(tasks),
    new Promise<void>((resolve) => (timer = setTimeout(resolve, limit))),
  ]);
  clearTimeout(timer);
}

// RPC values must be JSON, which has no `undefined`, such as a cleared error.
const json = <T>(value: T): T => JSON.parse(JSON.stringify(value));

// Stores each root session's targets, keeps its title prefix current, serves
// the targets to the CLI over RPC, and, given `status`, watches the PRs/MRs
// of the sessions that CLIs show.
export async function setupServer(
  ctx: Plugin.Context,
  lookups: TitleLookups,
  status?: StatusDependencies,
) {
  const pending = createKeyedQueue();
  const instructing = createKeyedQueue();
  const controller = new AbortController();
  // Set when cleanup starts. No title update or target change starts after
  // it, and one that is running stops before it writes, so it can't
  // overwrite what the replacement instance stores.
  let closing = false;
  // The last targets read or written per session, for checks that can't wait
  // for storage, such as whether a PR/MR is still a target before notifying.
  const known = new Map<string, Target[]>();
  // Counts each session's target writes. A read that overlapped a write may
  // return the old targets, so it doesn't update `known`.
  const revisions = new Map<string, number>();
  const revision = (sessionID: string) => revisions.get(sessionID) ?? 0;
  const bump = (sessionID: string) => revisions.set(sessionID, revision(sessionID) + 1);

  // The session each session was forked from, or null. Fork metadata never
  // changes, so one read per session is enough.
  const forkSources = new Map<string, string | null>();
  const forkSource = async (sessionID: string) => {
    if (forkSources.has(sessionID)) return forkSources.get(sessionID);
    try {
      const session = await ctx.session.get({ sessionID });
      const source = session?.fork?.sessionID ?? null;
      forkSources.set(sessionID, source);
      return source;
    } catch {
      return null;
    }
  };

  // A fork without a record of its own reads the nearest ancestor's record.
  // Its next update saves that state as its own, inside the keyed queue, so
  // nothing here can overwrite a concurrent target change.
  const storedState = async (sessionID: string): Promise<StoredState> => {
    let current = sessionID;
    for (let depth = 0; depth <= MAX_FORK_DEPTH; depth++) {
      const stored = (await ctx.storage.get(`sessions/${current}`)) as StoredState | undefined;
      if (stored) return stored;
      const source = await forkSource(current);
      if (!source) break;
      current = source;
    }
    return {};
  };

  const readState = async (sessionID: string) => {
    const stored = await storedState(sessionID);
    return {
      targets: Array.isArray(stored.targets) ? stored.targets : [],
      ...(stored.prefix ? { prefix: stored.prefix } : {}),
    };
  };

  async function stateFor(sessionID: string): Promise<SessionState> {
    const started = revision(sessionID);
    const state = await readState(sessionID);
    if (revision(sessionID) === started) known.set(sessionID, state.targets);
    return state;
  }

  // Bumps the revision before and after the write, so neither a read that
  // started before it nor one that started while it ran updates `known`.
  const save = async (sessionID: string, state: SessionState) => {
    if (closing) throw new Error('The plugin is reloading. Try again.');
    bump(sessionID);
    known.set(sessionID, state.targets);
    try {
      await ctx.storage.set(`sessions/${sessionID}`, {
        ...(state.targets.length ? { targets: state.targets } : {}),
        ...(state.prefix ? { prefix: state.prefix } : {}),
      });
    } finally {
      bump(sessionID);
    }
  };

  let watcher: Status | undefined;
  const rpc = await ctx.rpc.register(
    ForgeSessionRpc,
    implement({
      monitoringStatus: async ({ sessionID }) =>
        watcher
          ? json(await watcher.monitoringStatus(sessionID))
          : {
              enabled: false,
              directory: ctx.location.directory,
              sessionID,
              discovered: false,
              leased: false,
              polling: false,
              paused: false,
              humanFeedback: false,
              automatedFeedback: false,
              status: { loading: false },
              targets: [],
            },
      target: async ({ sessionID }) => targetOutput((await stateFor(sessionID)).targets),
      watch: async ({ clientID, keys, visible }) =>
        watcher
          ? { enabled: true, statuses: json(watcher.service.watch(clientID, keys, visible)) }
          : { enabled: false, statuses: {} },
      release: async ({ clientID }) => {
        watcher?.service.release(clientID);
        return {};
      },
      refresh: async ({ key }) =>
        watcher ? { enabled: true, snapshot: json(await watcher.refresh(key)) } : DISABLED,
      feedback: async () => (watcher ? watcher.inbox.list() : { items: [], paused: false }),
      markFeedbackRead: async ({ ids }) =>
        watcher ? watcher.inbox.markRead(ids) : { items: [], paused: false },
      acknowledgeFeedback: async ({ id }) =>
        watcher ? watcher.inbox.acknowledge(id) : { items: [], paused: false },
      summarizeFeedback: async ({ id }) => {
        if (!watcher) throw new Error('PR/MR status is disabled');
        return watcher.summarize(id);
      },
      actOnFeedback: async ({ id, retry }) => {
        if (!watcher) throw new Error('PR/MR status is disabled');
        return watcher.act(id, retry);
      },
      pauseFeedback: async ({ paused }) => {
        if (!watcher) return { items: [], paused: false };
        const state = await watcher.inbox.pause(paused);
        watcher.service.pauseFeedback(paused);
        await watcher.discovery.refresh();
        return state;
      },
    }),
  );

  const settings = statusOptions(ctx.options);
  if (settings.problems.length)
    void rpc.events
      .emit('notice', {
        message: `Some Forgekeeper options were ignored: ${settings.problems.join('; ')}`,
        variant: 'error',
      })
      .catch(() => {});
  if (status && settings.enabled) {
    watcher = await setupStatus(ctx, settings, status, {
      state: stateFor,
      storedTargets: async (sessionID) => (await readState(sessionID)).targets,
      isTarget: (sessionID, url) => includesRequest(known.get(sessionID) ?? [], url),
      publish: (key: string, snapshot: Snapshot) =>
        void rpc.events
          .emit('status', { directory: ctx.location.directory, key, snapshot: json(snapshot) })
          .catch(() => {}),
      notice: (notice) => void rpc.events.emit('notice', json(notice)).catch(() => {}),
      feedbackChanged: () =>
        void rpc.events
          .emit('feedbackChanged', { directory: ctx.location.directory })
          .catch(() => {}),
    });
  }

  async function update(sessionID: string): Promise<void> {
    const session = await ctx.session.get({ sessionID });
    if (session.parentID || !session.title) return;

    const directory = session.location.directory;
    if (directory !== ctx.location.directory) return;

    const state = await stateFor(sessionID);
    let prefix = targetsPrefix(state.targets);
    if (state.targets.length === 0) {
      const vcs = await ctx.vcs.get({ location: session.location });
      const info = vcs.data?.branch;
      const branch = info?.current;
      if (branch && !SKIP_BRANCHES.has(branch) && branch !== info?.default) {
        const found = await lookups.branch(directory);
        if (found) prefix = branchPrefix(found.forge, found.branch, found.number);
      }
    }

    // A branch lookup can outlast cleanup. Its result must not reach the
    // title or storage, which the replacement instance owns by then.
    if (closing) return;
    const title = reconcileTitle(session.title, prefix, state.prefix);
    if (title !== session.title) await ctx.session.update({ sessionID, title });
    await save(sessionID, { targets: state.targets, ...(prefix ? { prefix } : {}) });
  }

  // Runs one update at a time per session, so a target change and a turn
  // ending at once can't interleave their reads and writes.
  function schedule(sessionID: string, action = () => update(sessionID)): Promise<void> {
    if (closing) return Promise.reject(new Error('The plugin is reloading. Try again.'));
    return pending.run(sessionID, action);
  }

  // Infers the related issue of each PR/MR target from its source branch.
  // Targets the session already had were looked up when they were added.
  async function inferIssues(targets: Target[], previous: readonly Target[]) {
    const known = new Set(
      previous.filter((target) => !target.issueUrl).map((target) => target.url),
    );
    await mapLimit(targets, CONCURRENCY, async (target) => {
      if (target.issueUrl || target.branchIssue || known.has(target.url)) return;
      const request = targetRequest(target);
      const branch = request
        ? await lookups.sourceBranch(request, ctx.location.directory)
        : undefined;
      const issue = branch ? extractIssueNumber(branch) : undefined;
      if (issue) target.branchIssue = issue;
    });
  }

  const tools = await ctx.tool.transform((editor) => {
    editor.add({
      name: 'set_session_target',
      options: { codemode: false },
      description:
        'Set the issues, PRs, or MRs this session works on, for its title and PR/MR status. Use target for one full URL, or "branch" to return to branch-based naming. Use targets for several full URLs. The default operation, "replace", sets exactly the given targets; "add" keeps the current targets, and "remove" drops the given ones. Call it after creating a PR/MR for the current task. Without issue_url, the related issue is inferred from the PR/MR source branch name. This only changes local session metadata.',
      input: {
        type: 'object',
        properties: {
          target: {
            type: 'string',
            description: 'Full GitHub/GitLab issue, PR, or MR URL, or "branch".',
          },
          targets: {
            type: 'array',
            items: { type: 'string' },
            minItems: 1,
            maxItems: MAX_TARGETS,
            description: 'Several full GitHub/GitLab issue, PR, or MR URLs, instead of target.',
          },
          operation: {
            type: 'string',
            enum: ['replace', 'add', 'remove'],
            description: 'How the given targets change the current ones. Defaults to "replace".',
          },
          issue_url: {
            type: 'string',
            description:
              'Optional full URL of an established related issue for target, or for every PR/MR in targets. Omit when unknown.',
          },
        },
        additionalProperties: false,
      },
      execute: async (input, { sessionID }) => {
        const change = parseTargetChange(input);
        let result: { targets: Target[]; missing: string[] } = { targets: [], missing: [] };
        await schedule(sessionID, async () => {
          const session = await ctx.session.get({ sessionID });
          if (session.parentID || session.location.directory !== ctx.location.directory) {
            throw new Error('Session targets can only be set in the current root session.');
          }
          // A target would make the linked session a second owner of the PR/MR.
          if (linkedOwner(session as DirectorySession))
            throw new Error(
              'This session runs a Forgekeeper task for another session, which keeps the targets. Set targets there.',
            );
          const state = await stateFor(sessionID);
          result = applyTargetChange(state.targets, change);
          await inferIssues(result.targets, state.targets);
          await save(sessionID, {
            targets: result.targets,
            ...(state.prefix ? { prefix: state.prefix } : {}),
          });
          watcher?.targetsChanged(sessionID, result.targets);
          await instruct(sessionID).catch(() => {});
          await rpc.events.emit('targetChanged', { sessionID, ...targetOutput(result.targets) });
          await update(sessionID);
        });
        return { content: toolResult(result.targets, result.missing) };
      },
    });
    // Offered only in review summaries whose comments link to other notes;
    // the context hook removes it from every other request.
    if (watcher) {
      const summaries = watcher;
      editor.add({
        name: LINKED_NOTE_TOOL,
        options: { codemode: false },
        description:
          'Read a note that the review comments being summarized link to. Works only during a Forgekeeper review summary, and only for the links its request lists as readable.',
        input: {
          type: 'object',
          properties: {
            url: { type: 'string', description: 'One of the readable links, exactly as listed.' },
          },
          required: ['url'],
          additionalProperties: false,
        },
        execute: async (input, { sessionID }) => ({
          content: await summaries.fetchLinked(sessionID, (input as { url?: unknown })?.url),
        }),
      });
    }
  });

  // Each answer is a report that a tool-free turn shows, or undefined when
  // the command started a turn of its own, such as a summary.
  async function feedbackCommand(
    status: Status,
    sessionID: string,
    input: string,
  ): Promise<string | undefined> {
    const action = parseFeedbackAction(input);
    if (action.kind === 'invalid') return invalidFeedbackReport(action.input);
    const state = await status.inbox.list();
    if (action.kind === 'list') return feedbackReport(state, sessionID);
    const items = sessionItems(state, sessionID);
    const chosen =
      action.which === 'all'
        ? items
        : items.filter((item) => feedbackRef(item.id) === action.which);
    if (action.which !== 'all' && chosen.length > 1)
      return 'Ambiguous update ID. Use the feedback panel.';
    if (chosen.length === 0)
      return feedbackReport(
        state,
        sessionID,
        action.which === 'all' ? undefined : `No pending update with ID ${action.which}.`,
      );
    if (action.kind === 'summarize') {
      await status.summarize(chosen[0].id);
      return undefined;
    }
    let next = state;
    for (const item of chosen) next = await status.inbox.acknowledge(item.id);
    const note =
      chosen.length === 1
        ? `Acknowledged: ${chosen[0].title}`
        : `Acknowledged ${chosen.length} updates.`;
    return feedbackReport(next, sessionID, note);
  }

  // Without status, the commands have nothing to show, and the CLI's own
  // commands explain why.
  const commands = watcher
    ? await ctx.command.transform((editor) => {
        const status = watcher!;
        editor.add({
          name: STATUS_COMMAND,
          description: 'Show the PR/MR status of this session in the conversation',
          execute: async ({ sessionID }) =>
            status.relay(sessionID, STATUS_TITLE, statusReport(await status.refresh(sessionID))),
        });
        editor.add({
          name: FEEDBACK_COMMAND,
          description: 'List, acknowledge, or summarize review updates in the conversation',
          execute: async ({ sessionID, prompt }) => {
            let report: string | undefined;
            try {
              report = await feedbackCommand(status, sessionID, prompt.text ?? '');
            } catch (error) {
              report = `Forgekeeper could not complete /${FEEDBACK_COMMAND}: ${error instanceof Error ? error.message : String(error)}`;
            }
            if (report) await status.relay(sessionID, FEEDBACK_TITLE, report);
          },
        });
      })
    : undefined;

  async function writeInstructions(sessionID: string): Promise<void> {
    if (closing) return;
    const state = await stateFor(sessionID);
    const value = `Current session target: ${describeTargets(state.targets)}.`;
    const entries = await ctx.session.instructions.entry.list({ sessionID });
    if (entries.some((entry) => entry.key === TARGET_KEY && entry.value === value)) return;
    if (closing) return;
    await ctx.session.instructions.entry.put({ sessionID, key: TARGET_KEY, value });
  }

  function instruct(sessionID: string): Promise<void> {
    return instructing.run(sessionID, () => writeInstructions(sessionID));
  }

  // Without monitoring, such as after `status` is turned off, a
  // Forgekeeper message queued earlier can still start a step. Its record
  // isn't read then: the step only says the review text is unavailable.
  // Sessions whose latest request was such a step, for the backstops.
  const orphaned = new Set<string>();
  // A tag counts unless the context shows a user prompt, which may quote one.
  async function orphanedStep(event: SummaryRequest): Promise<boolean> {
    if (!taggedInput(event.messages)) {
      const records = await ctx.storage.scan({ prefix: summaryPrefix(event.sessionID) });
      if (!records.entries.length) return false;
    }
    try {
      const input = turnInput(await ctx.session.context({ sessionID: event.sessionID }));
      // Without an input, such as after a compaction, the step may be one.
      return !input || input.type !== 'user';
    } catch {
      return true;
    }
  }

  // A summary turn's request is replaced before anything else runs, and its
  // failures propagate, so the request never runs with the session's tools.
  // A failure in the guidance must not block the request, so it's skipped.
  await ctx.session.hook('context', async (event) => {
    if (!watcher) {
      const input = turnInput(await ctx.session.context({ sessionID: event.sessionID }));
      let preparing = input?.id.startsWith(PREPARE_PREFIX);
      if (!input) {
        const claims = status?.reviewClaims ?? createReviewClaims();
        try {
          preparing = !!(await storedPreparation(ctx, claims, event.sessionID));
        } finally {
          if (!status?.reviewClaims) claims.close();
        }
      }
      if (preparing)
        throw new Error(
          'Review preparation is disabled. Enable Forgekeeper status before resuming this task.',
        );
    }
    if (watcher) {
      // A preparation turn that can't be confirmed, such as when the
      // session's context can't be read, still gets a summary's
      // restrictions when one applies; otherwise its request fails.
      let preparing = false;
      let failure: { error: unknown } | undefined;
      try {
        preparing = await watcher.prepareAutomation(event);
      } catch (error) {
        failure = { error };
      }
      if (!preparing && (await watcher.prepareSummary(event))) return;
      if (failure) throw failure.error;
    } else if (await orphanedStep(event)) {
      orphaned.add(event.sessionID);
      restrictRequest(event, summarySystem(false), UNAVAILABLE_TEXT);
      return;
    } else orphaned.delete(event.sessionID);
    if (event.tools) delete event.tools[LINKED_NOTE_TOOL];
    try {
      if (!(await ownsSession(event.sessionID))) return;
      event.system.push({ type: 'text', text: GUIDANCE.join('\n') });
      await instruct(event.sessionID);
    } catch {
      // The request goes ahead without the guidance.
    }
  });

  // A compaction summarizes the stored transcript, where a linked session's
  // task is only a placeholder. A failure fails the compaction, so the
  // summary never stands in for a task it doesn't hold.
  await ctx.session.hook('compaction', async (event) => {
    await watcher?.prepareCompaction(event);
  });

  // OpenCode reads instruction entries before a step's request reaches the
  // context hook, and announces later changes in another step. Writing the
  // entry when a prompt is admitted makes it part of the first step's
  // instructions. The context hook still writes it for sessions without one,
  // such as those that started with a synthetic message.
  await ctx.session.hook('prompt', async (event) => {
    try {
      if (await ownsSession(event.sessionID)) await instruct(event.sessionID);
    } catch {
      // The prompt is admitted anyway, and the context hook writes the entry.
    }
  });

  // Linked sessions get no target guidance: their owner keeps the targets.
  async function ownsSession(sessionID: string): Promise<boolean> {
    const session = await ctx.session.get({ sessionID });
    return (
      !session.parentID &&
      session.location.directory === ctx.location.directory &&
      !linkedOwner(session as DirectorySession)
    );
  }

  // Backstops for a summary turn whose request still reached tools, such as
  // after a hook ordering change. Each refuses the action outright. The
  // linked-note tool checks its own calls, and asks for no permissions.
  // They stay without monitoring too, for steps of messages queued earlier.
  const summarizing = async (sessionID: string) =>
    watcher ? watcher.summarizing(sessionID) : orphaned.has(sessionID);
  await ctx.tool.hook('execute.before', async (event) => {
    if (watcher && event.tool === LINKED_NOTE_TOOL) return;
    if (await summarizing(event.sessionID))
      throw new Error('Tools are disabled while Forgekeeper summarizes review feedback.');
  });
  await ctx.permission.hook('evaluate', async (event) => {
    if (!(await summarizing(event.sessionID))) return;
    event.effect = 'deny';
    event.message = 'Forgekeeper review summaries run without tools.';
  });

  void (async () => {
    for await (const event of ctx.event.subscribe({
      types: [
        'session.renamed',
        'session.moved',
        'session.archived',
        'session.unarchived',
        'session.deleted',
        'session.compaction.ended',
        'session.execution.started',
        'session.execution.succeeded',
        'session.execution.failed',
        'session.execution.interrupted',
        'vcs.branch.updated',
      ],
      signal: controller.signal,
    })) {
      const { type } = event as { type: string };
      const sessionID = (event.data as { sessionID?: string } | undefined)?.sessionID;
      if ((type === 'session.renamed' || type === 'session.execution.succeeded') && sessionID) {
        void schedule(sessionID).catch(() => {});
      }
      if (type === 'session.renamed' && sessionID)
        void watcher?.titleChanged(sessionID).catch(() => {});
      if (type === 'session.moved' && sessionID) watcher?.sessionMoved(sessionID);
      if (
        sessionID &&
        (type === 'session.archived' ||
          type === 'session.unarchived' ||
          type === 'session.deleted' ||
          type === 'session.compaction.ended' ||
          type === 'session.execution.started' ||
          type === 'session.execution.interrupted')
      )
        void watcher?.discovery.refresh(sessionID);
      if (
        sessionID &&
        (type === 'session.execution.succeeded' || type === 'session.execution.failed')
      )
        watcher?.turnEnded(sessionID);
      // A shutdown doesn't end the turn: the resumed execution continues it.
      const reason = (event.data as { reason?: string } | undefined)?.reason;
      if (
        sessionID &&
        (type === 'session.execution.succeeded' ||
          type === 'session.execution.failed' ||
          type === 'session.execution.interrupted') &&
        !(type === 'session.execution.interrupted' && reason === 'shutdown')
      )
        watcher?.executionEnded(
          sessionID,
          type === 'session.execution.succeeded' ? 'succeeded' : 'failed',
          (event as { created?: number }).created ?? Date.now(),
        );
      if (type === 'vcs.branch.updated') {
        const location = (event as { location?: { directory?: string } }).location;
        if (!location?.directory || location.directory === ctx.location.directory)
          void watcher?.branchChanged().catch(() => {});
      }
    }
  })().catch((error) => {
    // Without events, titles and statuses stop following renames, turns, and
    // branch switches until the plugin reloads.
    if (controller.signal.aborted) return;
    const reason = error instanceof Error ? error.message : String(error);
    void rpc.events
      .emit('notice', {
        message: `Session title and PR/MR status updates stopped: ${reason}`,
        variant: 'error',
      })
      .catch(() => {});
  });

  // Stops new work, waits for running title updates and target changes, then
  // stops the status watchers.
  return async () => {
    closing = true;
    controller.abort();
    await drain(pending.tasks(), DRAIN_TIME);
    await watcher?.dispose();
    await commands?.dispose();
    await tools.dispose();
    await rpc.dispose();
  };
}

import { existsSync, readFileSync } from 'node:fs';
import { appendFile, mkdir } from 'node:fs/promises';
import { homedir, hostname } from 'node:os';
import { basename, dirname, join } from 'node:path';
import type { Plugin } from '@opencode/plugin';
import {
  createAgentStateTracker,
  createLocationFilter,
  TRACKED_EVENTS,
  type FormInfo,
  type OpenCodeEvent,
  type WaitingDetail,
} from '../../_shared/src/index.ts';
import pkg from '../package.json' with { type: 'json' };
import { HomeAssistantRpc } from './rpc.ts';

type AgentState = 'busy' | 'idle' | 'waiting' | 'error';
type WebhookUrlEntry = string | string[];
type LogLevel = 'debug' | 'info' | 'error';
type FormAnswer = Record<string, string | string[]>;

export interface Config {
  webhookUrl?: string;
  webhookUrls?: Partial<Record<AgentState | 'default', WebhookUrlEntry>>;
  haApiUrl?: string;
  haToken?: string;
  permissionResponseEntity?: string;
  permissionTimeout?: number;
  debug?: boolean;
  debugLogPath?: string;
}

export interface HomeAssistantDeps {
  directory: string;
  config: Config;
  log: (level: LogLevel, message: string) => Promise<void> | void;
  replyPermission: (
    sessionID: string,
    requestID: string,
    decision: 'once' | 'reject',
  ) => Promise<void>;
  replyForm: (sessionID: string, formID: string, answer: FormAnswer) => Promise<void>;
}

interface WebhookPayload {
  state: string;
  hostname: string;
  project: string;
  sessionId?: string;
  durationMs?: number;
  waiting?: WaitingDetail;
}

interface HaEntityState {
  state: string;
  attributes: Record<string, unknown>;
}

interface WebhookFailure {
  url: string;
  reason: string;
}

interface SessionTimes {
  start: number;
  lastActivity: number;
}

type PollResult =
  | { kind: 'permission'; response: 'allow' | 'deny' }
  | { kind: 'question'; optionIndex: number }
  | { kind: 'invalid' };

type PollOutcome = PollResult | { kind: 'no-config' } | { kind: 'canceled' } | { kind: 'timeout' };

const DEFAULT_PERMISSION_TIMEOUT = 120;
const DEFAULT_RESPONSE_ENTITY = 'input_text.opencode_permission_response';
const DEFAULT_DEBUG_LOG_PATH = join(homedir(), '.local', 'state', 'opencode', 'homeassistant.log');
const POLL_INTERVAL_MS = 2000;
const STALE_SESSION_TIMEOUT_MS = 10 * 60 * 1000;
const STALE_SESSION_SWEEP_INTERVAL_MS = 60 * 1000;
const WEBHOOK_TIMEOUT_MS = 5000;
const WEBHOOK_DRAIN_TIMEOUT_MS = 6000;

export function loadConfig(): Config {
  const configPath =
    process.env['OPENCODE_HA_CONFIG_PATH'] ??
    join(homedir(), '.config', 'opencode', 'opencode-homeassistant.json');

  if (existsSync(configPath)) {
    try {
      const raw = readFileSync(configPath, 'utf-8');
      return JSON.parse(raw) as Config;
    } catch {
      return {};
    }
  }

  return {};
}

function resolveEnvVars(value: string): string {
  return value.replace(/\$\{([^}]+)}/g, (_match, name: string) => process.env[name] ?? '');
}

function resolveWebhookUrls(config: Config, state: AgentState): string[] {
  const entry = config.webhookUrls?.[state] ?? config.webhookUrls?.default;
  if (entry) return (Array.isArray(entry) ? entry : [entry]).filter(Boolean);
  if (config.webhookUrl) return [config.webhookUrl];
  return [];
}

function sendWebhook(urls: string[], payload: WebhookPayload): Promise<WebhookFailure[]> {
  return Promise.all(
    urls.map(async (url): Promise<WebhookFailure | undefined> => {
      try {
        const resp = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
          signal: AbortSignal.timeout(WEBHOOK_TIMEOUT_MS),
        });
        if (!resp.ok) return { url, reason: `HTTP ${resp.status}` };
        return undefined;
      } catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        const timedOut = error instanceof Error && error.name === 'TimeoutError';
        return {
          url,
          reason: timedOut ? `timed out after ${WEBHOOK_TIMEOUT_MS}ms` : detail,
        };
      }
    }),
  ).then((results) => results.filter((r): r is WebhookFailure => r !== undefined));
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function describeForeignState(state: string): string {
  const segments = state.split(':');
  if (segments[0] === 'question') return `kind=question, requestID=${segments[1] ?? '(empty)'}`;
  return `kind=permission, id=${segments[0] ?? '(empty)'}`;
}

function parseResponse(state: string, requestId: string): PollResult | undefined {
  const segments = state.split(':');

  if (segments[0] === 'question') {
    if (segments.length !== 3 || segments[1] !== requestId) return undefined;
    const optionIndex = Number(segments[2]);
    if (!Number.isInteger(optionIndex) || optionIndex < 0) return { kind: 'invalid' };
    return { kind: 'question', optionIndex };
  }

  if (segments.length !== 2 || segments[0] !== requestId) return undefined;
  const response = segments[1];
  if (response === 'allow' || response === 'always')
    return { kind: 'permission', response: 'allow' };
  if (response === 'deny') return { kind: 'permission', response: 'deny' };
  return undefined;
}

async function fetchHaEntity(
  apiUrl: string,
  token: string,
  entityId: string,
): Promise<{ entity: HaEntityState } | { failure: string }> {
  try {
    const resp = await fetch(`${apiUrl}/states/${entityId}`, {
      headers: { Authorization: `Bearer ${token}` },
      signal: AbortSignal.timeout(5000),
    });
    if (!resp.ok) return { failure: describeHaHttpFailure(resp.status, entityId) };
    return { entity: (await resp.json()) as HaEntityState };
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    return { failure: `request to ${apiUrl} failed (${detail})` };
  }
}

function describeHaHttpFailure(status: number, entityId: string): string {
  if (status === 401 || status === 403) {
    return `HTTP ${status}, the long-lived token was rejected by Home Assistant`;
  }
  if (status === 404) {
    return `HTTP 404, entity ${entityId} does not exist (create the input_text helper in Home Assistant)`;
  }
  return `HTTP ${status}`;
}

async function setHaEntity(
  apiUrl: string,
  token: string,
  entityId: string,
  state: string,
): Promise<string | undefined> {
  try {
    const resp = await fetch(`${apiUrl}/states/${entityId}`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${token}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ state }),
      signal: AbortSignal.timeout(5000),
    });
    if (!resp.ok) return describeHaHttpFailure(resp.status, entityId);
    return undefined;
  } catch (error) {
    return error instanceof Error ? error.message : String(error);
  }
}

export function createHomeAssistant(deps: HomeAssistantDeps) {
  const { config } = deps;
  const project = basename(deps.directory);
  const host = hostname();
  const sessions = new Map<string, SessionTimes>();
  const repliedPermissions = new Set<string>();
  const activePermissionPolls = new Set<string>();
  const inflightWebhooks = new Map<string, Promise<void>>();
  const forms = new Map<string, FormInfo>();

  function elapsedSince(sessionId?: string): number | undefined {
    if (!sessionId) return undefined;
    const session = sessions.get(sessionId);
    return session ? Date.now() - session.start : undefined;
  }

  function recordActivity(sessionId: string, now = Date.now()): boolean {
    const session = sessions.get(sessionId);
    if (session) {
      session.lastActivity = now;
      return false;
    }
    sessions.set(sessionId, { start: now, lastActivity: now });
    return true;
  }

  function send(
    state: AgentState,
    sessionId?: string,
    extra?: { durationMs?: number; waiting?: WaitingDetail },
  ): Promise<void> {
    const urls = resolveWebhookUrls(config, state);
    if (urls.length === 0) {
      if (state === 'waiting') {
        return report(
          'no webhook URL configured for the waiting state, so no notification was sent',
          undefined,
        );
      }
      return Promise.resolve();
    }
    const payload: WebhookPayload = { state, hostname: host, project, sessionId };
    if (extra?.durationMs !== undefined) payload.durationMs = extra.durationMs;
    if (extra?.waiting) payload.waiting = extra.waiting;

    const key = sessionId ?? '';
    const previous = inflightWebhooks.get(key) ?? Promise.resolve();
    const promise = previous
      .then(() => sendWebhook(urls, payload))
      .then(async (failures) => {
        for (const failure of failures) {
          await report(
            `${state} webhook to ${failure.url} failed: ${failure.reason}${
              state === 'waiting' ? ' (no notification was delivered)' : ''
            }`,
            undefined,
          );
        }
      })
      .finally(() => {
        if (inflightWebhooks.get(key) === promise) inflightWebhooks.delete(key);
      });
    inflightWebhooks.set(key, promise);
    return promise;
  }

  function sweepStaleSessions(now: number): void {
    for (const [sessionId, session] of sessions.entries()) {
      if (tracker.hasWait(sessionId)) continue;
      if (now - session.lastActivity >= STALE_SESSION_TIMEOUT_MS) {
        const durationMs = now - session.start;
        sessions.delete(sessionId);
        send('idle', sessionId, { durationMs });
      }
    }
  }

  function unsetTokenVars(): string[] {
    if (!config.haToken) return [];
    return [...config.haToken.matchAll(/\$\{([^}]+)}/g)]
      .map((match) => match[1] as string)
      .filter((name) => !process.env[name]);
  }

  function describeUnsetTokenVars(names: string[]): string {
    return `haToken references ${names.join(', ')}, which ${
      names.length > 1 ? 'are' : 'is'
    } not set in the opencode process environment`;
  }

  function describeMissingHaConfig(): string | undefined {
    if (!config.haApiUrl) return 'haApiUrl is not set';
    if (!config.haToken) return 'haToken is not set';
    if (resolveEnvVars(config.haToken)) return undefined;

    const unset = unsetTokenVars();
    if (unset.length > 0) return describeUnsetTokenVars(unset);
    return 'haToken resolved to an empty value';
  }

  function resolveHaConfig(): { apiUrl: string; token: string; entity: string } | undefined {
    if (!config.haApiUrl || !config.haToken) return undefined;
    const token = resolveEnvVars(config.haToken);
    if (!token) return undefined;
    return {
      apiUrl: config.haApiUrl.replace(/\/+$/, ''),
      token,
      entity: config.permissionResponseEntity ?? DEFAULT_RESPONSE_ENTITY,
    };
  }

  async function clearEntity(
    ha: { apiUrl: string; token: string; entity: string },
    requestId: string,
  ): Promise<void> {
    const failure = await setHaEntity(ha.apiUrl, ha.token, ha.entity, '');
    if (failure) {
      await report(`${requestId}: could not clear entity ${ha.entity}: ${failure}`, undefined);
    }
  }

  async function pollForResponse(requestId: string): Promise<PollOutcome> {
    const ha = resolveHaConfig();
    if (!ha) {
      await report(
        `${requestId}: not polling because ${describeMissingHaConfig() ?? 'the Home Assistant config is unavailable'}`,
        undefined,
      );
      return { kind: 'no-config' };
    }

    const partiallyUnset = unsetTokenVars();
    if (partiallyUnset.length > 0) {
      await report(
        `${requestId}: ${describeUnsetTokenVars(partiallyUnset)}, so the token is incomplete`,
        undefined,
      );
    }

    const timeoutMs = (config.permissionTimeout ?? DEFAULT_PERMISSION_TIMEOUT) * 1000;
    const deadline = Date.now() + timeoutMs;
    activePermissionPolls.add(requestId);
    await trace(`${requestId}: poll started, entity=${ha.entity}, timeout=${timeoutMs}ms`);

    let polls = 0;
    let mismatches = 0;
    let fetchFailures = 0;

    try {
      while (Date.now() < deadline) {
        if (repliedPermissions.delete(requestId)) {
          await trace(`${requestId}: poll canceled after ${polls} polls (answered elsewhere)`);
          return { kind: 'canceled' };
        }

        polls += 1;
        const read = await fetchHaEntity(ha.apiUrl, ha.token, ha.entity);
        if ('failure' in read) {
          fetchFailures += 1;
          if (fetchFailures === 1) {
            await report(
              `${requestId}: cannot read entity ${ha.entity} from Home Assistant: ${read.failure}`,
              undefined,
            );
          }
        } else if (read.entity.state) {
          const entity = read.entity;
          const result = parseResponse(entity.state, requestId);
          if (result?.kind === 'invalid') {
            await report(
              `${requestId}: response present but option index is not a valid index`,
              undefined,
            );
            await clearEntity(ha, requestId);
            return result;
          }
          if (result) {
            await trace(`${requestId}: matched ${result.kind} response after ${polls} polls`);
            await clearEntity(ha, requestId);
            return result;
          }
          mismatches += 1;
          if (mismatches === 1) {
            await trace(
              `${requestId}: observed a response for a different request (${describeForeignState(entity.state)})`,
            );
          }
        }
        await sleep(POLL_INTERVAL_MS);
      }
    } finally {
      activePermissionPolls.delete(requestId);
    }

    await report(
      `${requestId}: timed out after ${timeoutMs}ms (${polls} polls, ${mismatches} responses for other requests, ${fetchFailures} failed reads)`,
      undefined,
    );
    return { kind: 'timeout' };
  }

  function describeError(error: unknown): string | undefined {
    if (error === undefined || error === null) return undefined;
    if (error instanceof Error) return error.message;
    if (typeof error === 'object') {
      try {
        return JSON.stringify(error);
      } catch {
        return '[unserializable error]';
      }
    }
    return String(error);
  }

  async function log(level: LogLevel, message: string): Promise<void> {
    try {
      await deps.log(level, message);
    } catch {
      return;
    }
  }

  async function report(message: string, error: unknown): Promise<void> {
    const detail = describeError(error);
    await log('error', detail ? `${message}: ${detail}` : message);
  }

  async function trace(message: string): Promise<void> {
    await log('debug', message);
  }

  async function announce(message: string): Promise<void> {
    await log('info', message);
  }

  async function answerQuestion(sessionID: string, formID: string): Promise<void> {
    if (activePermissionPolls.has(formID)) {
      await trace(`${formID}: already polling, not starting a second poll`);
      return;
    }

    const field = forms
      .get(formID)
      ?.fields.find((candidate) => !('hidden' in candidate && candidate.hidden));
    const options = field && 'options' in field ? (field.options ?? []) : [];
    await trace(`${formID}: answerQuestion started, ${options.length} options offered`);

    const result = await pollForResponse(formID);
    if (result.kind !== 'question') {
      if (result.kind === 'permission') {
        await report(`${formID}: expected a question response but got a permission one`, undefined);
      }
      return;
    }

    const option = options[result.optionIndex];
    if (!field || !option) {
      await report(
        `${formID}: option index ${result.optionIndex} is out of range (${options.length} options offered)`,
        undefined,
      );
      return;
    }
    await trace(`${formID}: option index ${result.optionIndex} resolved to a value`);

    const answer = { [field.key]: field.type === 'multiselect' ? [option.value] : option.value };
    try {
      await deps.replyForm(sessionID, formID, answer);
      await trace(`${formID}: reply relayed to the CLI`);
    } catch (error) {
      await report(`${formID}: reply could not be relayed`, error);
    }
  }

  async function answerPermission(sessionID: string, requestID: string): Promise<void> {
    const result = await pollForResponse(requestID);
    if (result.kind !== 'permission') return;
    try {
      await deps.replyPermission(
        sessionID,
        requestID,
        result.response === 'allow' ? 'once' : 'reject',
      );
    } catch (error) {
      await report(`${requestID}: permission reply rejected`, error);
    }
  }

  function describeStartup(): string {
    const ha = resolveHaConfig();
    const entity = config.permissionResponseEntity ?? DEFAULT_RESPONSE_ENTITY;
    const timeout = config.permissionTimeout ?? DEFAULT_PERMISSION_TIMEOUT;
    const remote = ha ? 'enabled' : `disabled (${describeMissingHaConfig()})`;
    return `started version=${pkg.version}, entity=${entity}, permissionTimeout=${timeout}s, remoteReplies=${remote}`;
  }

  const tracker = createAgentStateTracker({
    emitRepeatedBusy: true,
    onWaiting: async (sessionID, waiting) => {
      const id = waiting.id ?? '(unresolved)';
      if (recordActivity(sessionID)) {
        await trace(
          `${id}: reactivated idle session ${sessionID} from incoming ${waiting.reason} request`,
        );
      }

      await send('waiting', sessionID, {
        durationMs: elapsedSince(sessionID),
        waiting,
      });

      if (!waiting.id) return;
      const answer =
        waiting.reason === 'question'
          ? answerQuestion(sessionID, waiting.id)
          : answerPermission(sessionID, waiting.id);
      void answer.catch((error: unknown) => report(`${id}: remote reply failed`, error));
    },
    onBusy: async (sessionID) => {
      if (!sessions.has(sessionID)) return;
      recordActivity(sessionID);
      await send('busy', sessionID, { durationMs: elapsedSince(sessionID) });
    },
    onIdle: async (sessionID) => {
      if (!sessions.has(sessionID)) return;
      const durationMs = elapsedSince(sessionID);
      sessions.delete(sessionID);
      await send('idle', sessionID, { durationMs });
    },
    onError: async (sessionID) => {
      if (!sessions.has(sessionID)) return;
      const durationMs = elapsedSince(sessionID);
      sessions.delete(sessionID);
      await send('error', sessionID, { durationMs });
    },
    onResolved: (_sessionID, requestID) => {
      if (activePermissionPolls.has(requestID)) repliedPermissions.add(requestID);
    },
  });

  const staleSessionSweep = setInterval(
    () => sweepStaleSessions(Date.now()),
    STALE_SESSION_SWEEP_INTERVAL_MS,
  );
  staleSessionSweep.unref();

  void announce(describeStartup());

  async function handle(event: OpenCodeEvent): Promise<void> {
    if (event.type === 'session.execution.started') recordActivity(event.data.sessionID);
    if (event.type === 'form.created') forms.set(event.data.form.id, event.data.form);
    await tracker.handle(event);
    if (event.type === 'form.replied' || event.type === 'form.cancelled') {
      forms.delete(event.data.id);
    }
  }

  async function dispose(): Promise<void> {
    clearInterval(staleSessionSweep);
    for (const [sessionId, session] of sessions.entries()) {
      sessions.delete(sessionId);
      void send('idle', sessionId, { durationMs: Date.now() - session.start });
    }
    await Promise.race([
      Promise.all([...inflightWebhooks.values()]),
      sleep(WEBHOOK_DRAIN_TIMEOUT_MS),
    ]);
  }

  return { handle, dispose };
}

function expandHome(path: string): string {
  return path === '~' || path.startsWith('~/') ? join(homedir(), path.slice(1)) : path;
}

export function createDebugLog(config: Config): HomeAssistantDeps['log'] {
  if (!config.debug) return () => {};
  const path = expandHome(config.debugLogPath ?? DEFAULT_DEBUG_LOG_PATH);
  let ready: Promise<unknown> | undefined;
  return async (level, message) => {
    ready ??= mkdir(dirname(path), { recursive: true }).catch(() => {});
    await ready;
    await appendFile(path, `${new Date().toISOString()} ${level} ${message}\n`).catch(() => {});
  };
}

export default {
  id: 'opencode-homeassistant',
  async setup(ctx) {
    const config: Config = { ...loadConfig(), ...(ctx.options as Config) };
    const rpc = await ctx.rpc.register(HomeAssistantRpc, {});
    const homeAssistant = createHomeAssistant({
      directory: ctx.location.directory,
      config,
      log: createDebugLog(config),
      replyPermission: (sessionID, requestID, decision) =>
        ctx.permission.reply({ sessionID, requestID, decision }),
      replyForm: (sessionID, formID, answer) =>
        rpc.events.emit('answer', { sessionID, formID, answer }),
    });

    const owns = createLocationFilter(
      ctx.location.directory,
      async (sessionID) => (await ctx.session.get({ sessionID })).location.directory,
    );

    const controller = new AbortController();
    void (async () => {
      for await (const event of ctx.event.subscribe({
        types: [...TRACKED_EVENTS],
        signal: controller.signal,
      })) {
        if (await owns(event)) await homeAssistant.handle(event);
      }
    })().catch(() => {});

    return async () => {
      controller.abort();
      await homeAssistant.dispose();
    };
  },
} satisfies Plugin.Plugin;

import type { Plugin } from '@opencode/plugin';
import { randomUUID } from 'node:crypto';
import { rejectReason, type SessionRef } from './match.ts';
import { reply, waitForReply } from './pending.ts';
import { LIMIT } from './present.ts';
import { SessionSearchRpc, type OpenAction, type SearchRequest } from './rpc.ts';
import { runSearch } from './run.ts';
import {
  OPEN_DESCRIPTION,
  SEARCH_DESCRIPTION,
  openInput,
  searchInput,
  searchOptions,
  type SearchInput,
} from './tool.ts';

const REPLY_TIMEOUT_MS = 3_000;
const MAX_ANCESTORS = 10;

type SessionGet = (input: { sessionID: string }) => Promise<SessionRef & { title?: string }>;

async function ancestry(get: SessionGet, session: SessionRef): Promise<string[]> {
  const ids = [session.id];
  let parentID = session.parentID;
  while (parentID && ids.length <= MAX_ANCESTORS) {
    ids.push(parentID);
    parentID = (await get({ sessionID: parentID })).parentID;
  }
  return ids;
}

function describe(action: OpenAction): string {
  return action === 'tab' ? 'focused its tab' : 'navigated to it';
}

function databaseOption(options: unknown): string | undefined {
  if (!options || typeof options !== 'object') return undefined;
  const value = (options as Record<string, unknown>)['database'];
  return typeof value === 'string' && value ? value : undefined;
}

export default {
  id: 'opencode-session-finder',
  async setup(ctx) {
    const get = ctx.session.get as unknown as SessionGet;
    const database = databaseOption(ctx.options);

    const rpc = await ctx.rpc.register(SessionSearchRpc, {
      handled: async (input) => {
        const { requestID, action } = input as { requestID: string; action: OpenAction };
        reply(requestID, action);
        return {};
      },
      search: async (input, { signal }) => {
        const request = input as SearchRequest;
        const result = await runSearch(
          {
            query: request.query,
            database,
            limit: request.limit ?? LIMIT,
            excerpts: 1,
            currentSessionID: request.sessionID,
            cwd: request.directory ?? ctx.location.directory,
            titles: request.titles ?? false,
          },
          signal,
        );
        return result as unknown as Record<string, unknown>;
      },
    });

    const tools = await ctx.tool.transform((editor) => {
      editor.add({
        name: 'search_sessions',
        description: SEARCH_DESCRIPTION,
        input: searchInput,
        execute: async (input, { sessionID, signal }) => {
          const session = await get({ sessionID });
          const result = await runSearch(
            searchOptions(input as SearchInput, {
              sessionID,
              directory: session.location.directory,
              database,
            }),
            signal,
          );
          return { content: JSON.stringify(result, null, 2) };
        },
      });

      editor.add({
        name: 'open_session',
        description: OPEN_DESCRIPTION,
        input: openInput,
        execute: async (input, { sessionID, signal }) => {
          const { session_id: targetID, close_source: closeSource = false } = input as {
            session_id: string;
            close_source?: boolean;
          };
          const source = await get({ sessionID });
          let target: Awaited<ReturnType<SessionGet>>;
          try {
            target = await get({ sessionID: targetID });
          } catch {
            throw new Error(`Session ${targetID} was not found.`);
          }
          const reason = rejectReason(source, target);
          if (reason) throw new Error(reason);

          const sourceSessionIDs = await ancestry(get, source);
          const targetSessionIDs = await ancestry(get, target);
          const requestID = randomUUID();
          const replied = waitForReply(requestID, REPLY_TIMEOUT_MS, signal);
          await rpc.events.emit('requested', {
            requestID,
            sourceSessionIDs,
            sessionID: target.id,
            rootSessionID: targetSessionIDs[targetSessionIDs.length - 1]!,
            root: !target.parentID,
            closeSource,
          });
          const action = await replied;
          if (!action) {
            throw new Error(
              `No terminal showing this session opened ${target.id}. ` +
                `Reopen it with \`opencode --session ${target.id}\`.`,
            );
          }
          const title = target.title ? `"${target.title}" (${target.id})` : target.id;
          return { content: `Opened ${title}: the terminal ${describe(action)}.` };
        },
      });
    });

    return async () => {
      await tools.dispose();
      await rpc.dispose();
    };
  },
} satisfies Plugin.Plugin;
